const U=3,G=9.8,TA=U/G;
function Y(h){return 290-380*h;}
function f(v,d){if(Math.abs(v)<0.5*Math.pow(10,-d))v=0;return (v>0?'+':'')+v.toFixed(d);}
function T(id,x,y,text,role,align){const o={kind:'text',id,x,y,text};if(role)o.role=role;if(align)o.align=align;return o;}
function L(id,x1,y1,x2,y2,role,op){const o={kind:'line',id,from:{x:x1,y:y1},to:{x:x2,y:y2}};if(role)o.role=role;if(op!==undefined)o.opacity=op;return o;}
function A(id,x1,y1,x2,y2,role){return {kind:'arrow',id,from:{x:x1,y:y1},to:{x:x2,y:y2},role};}
function ballGroup(p,x,h,v,a,label){const o=[];const cy=Y(h);
o.push({kind:'circle',id:p+'ball',x,y:cy,w:28,role:'observed'});
if(Math.abs(v)>1e-4){const ey=cy-40*v;o.push(A(p+'v',x-34,cy,x-34,ey,'output'));o.push(T(p+'vl',x-48,ey+(v>0?-4:14),'v','output','middle'));}
else{o.push(T(p+'v0',x,cy-22,'v = 0','output','middle'));}
if(Math.abs(a)>1e-4){const ey=cy-8*a;o.push(A(p+'a',x+34,cy,x+34,ey,'warning'));o.push(T(p+'al',x+48,ey+14,'a','warning','middle'));}
else{o.push(T(p+'a0',x+52,cy+5,'a = 0','warning','start'));}
o.push(T(p+'name',x,50,label,'neutral','middle'));return o;}
export function evaluate({time}){
const t=sdk.clamp(Number(time)||0,0,2*TA);
const yT=U*t-0.5*G*t*t,vT=U-G*t,aT=-G;
const rel=t>=TA-1e-9,dt=Math.max(0,t-TA);
const yH=rel?-0.5*G*dt*dt:0,vH=rel?-G*dt:0,aH=rel?-G:0;
const o=[];
const ax=120;o.push(L('axis',ax,Y(0.5),ax,Y(-0.5),'neutral'));
o.push(T('axisl',ax,Y(0.5)-14,'height (m), up +','neutral','middle'));
[-0.4,-0.2,0,0.2,0.4].forEach((h,i)=>{o.push(L('tk'+i,ax-6,Y(h),ax,Y(h),'neutral'));o.push(T('tl'+i,ax-30,Y(h)+5,h.toFixed(1),'neutral','middle'));});
const xt=300,xh=500;
o.push(L('launch',xt-112,Y(0),xt-58,Y(0),'neutral'));
o.push(T('launchl',xt-85,Y(0)-12,'launch mark','neutral','middle'));
o.push(L('peak',xt-60,Y(U*U/(2*G)),xh+60,Y(U*U/(2*G)),'neutral',0.35));
const gy=Y(0)+16;
o.push(L('postL',xh-60,gy-6,xh-60,gy+6,'neutral'));o.push(L('postR',xh+60,gy-6,xh+60,gy+6,'neutral'));
if(rel){o.push(L('flapL',xh-60,gy,xh-76,gy+24,'input'));o.push(L('flapR',xh+60,gy,xh+76,gy+24,'input'));}
else{o.push(L('flapL',xh-60,gy,xh,gy,'input'));o.push(L('flapR',xh,gy,xh+60,gy,'input'));}
o.push(T('gatel',xh+95,gy+22,rel?'Release gate: open':'Release gate: closed','input','start'));
ballGroup('t',xt,yT,vT,aT,'Tossed ball').forEach(q=>o.push(q));
ballGroup('h',xh,yH,vH,aH,'Held ball').forEach(q=>o.push(q));
const rx=780;
o.push(T('r0',rx,90,'Tossed ball','observed','start'));
o.push(T('r1',rx,118,'v = '+f(vT,2)+' m/s','output','start'));
o.push(T('r2',rx,144,'a = '+f(aT,1)+' m/s²','warning','start'));
o.push(T('r3',rx,174,'height = '+yT.toFixed(3)+' m','neutral','start'));
o.push(T('r4',rx,230,'Held ball','observed','start'));
o.push(T('r5',rx,258,'v = '+f(vH,2)+' m/s','output','start'));
o.push(T('r6',rx,284,'a = '+f(aH,1)+' m/s²','warning','start'));
o.push(T('r7',rx,314,'height = '+f(yH,3)+' m','neutral','start'));
return {frame:{width:960,height:640,objects:o,readouts:[{id:'tossedVelocity',value:vT},{id:'tossedAcceleration',value:aT}]},quantities:{launchSpeed:U,gravity:G,velocity:vT,acceleration:aT,apexTime:TA,tossedVelocity:vT,tossedAcceleration:aT,heldVelocity:vH,heldHeight:yH,tossedHeight:yT}};}
